<?php
require_once __DIR__.'/../app/bootstrap.php';require_admin();
$active='messages';$pageTitle='বার্তা ও প্রোফাইল ব্যবস্থাপনা';$error='';$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
function aspi_message_upload(array $f): string { if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) throw new RuntimeException('প্রোফাইল ছবি আপলোড করা যায়নি।'); if(($f['size']??0)>5*1024*1024) throw new RuntimeException('ছবির সর্বোচ্চ সাইজ ৫ MB।'); $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if($ext===''||!@getimagesize($f['tmp_name']))throw new RuntimeException('শুধু JPG, PNG অথবা WEBP ছবি ব্যবহার করুন।');$dir=__DIR__.'/../uploads/site';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('ছবি সংরক্ষণের ফোল্ডার তৈরি করা যায়নি।');$name='message-profile-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('ছবি সংরক্ষণ করা যায়নি।');return 'live/uploads/site/'.$name; }
$values=[];for($i=1;$i<=3;$i++){foreach(['name','role','text','photo'] as $f)$values[$i][$f]='';}
$st=$pdo->query('SELECT setting_key,setting_value FROM site_settings');foreach($st->fetchAll() as $r){if(preg_match('/^message([1-3])_(name|role|text|photo)$/',$r['setting_key'],$m))$values[(int)$m[1]][$m[2]]=$r['setting_value'];}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$save=$values;for($i=1;$i<=3;$i++){$save[$i]['name']=trim((string)($_POST["message{$i}_name"]??''));$save[$i]['role']=trim((string)($_POST["message{$i}_role"]??''));$save[$i]['text']=trim((string)($_POST["message{$i}_text"]??''));if(mb_strlen($save[$i]['name'])>180||mb_strlen($save[$i]['role'])>180||mb_strlen($save[$i]['text'])>12000)throw new RuntimeException('নাম/পদবি বা বার্তার লেখা অনুমোদিত সীমার চেয়ে বড়।');if(!empty($_FILES["message{$i}_photo_upload"]['name']))$save[$i]['photo']=aspi_message_upload($_FILES["message{$i}_photo_upload"]);}
$up=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');for($i=1;$i<=3;$i++)foreach(['name','role','text','photo'] as $f)$up->execute(["message{$i}_{$f}",$save[$i][$f]]);try{$lg=$pdo->prepare('INSERT INTO activity_logs(admin_id,action,details,ip_address) VALUES(?,?,?,?)');$lg->execute([$_SESSION['admin_id'],'messages_updated','হোমপেজের বার্তা ও প্রোফাইল আপডেট',$_SERVER['REMOTE_ADDR']??'']);}catch(Throwable $ignored){}$_SESSION['flash']='বার্তা ও প্রোফাইল তথ্য সংরক্ষণ করা হয়েছে।';header('Location: messages.php');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'তথ্য সংরক্ষণ করা যায়নি। ডেটাবেজ সেটআপ যাচাই করুন।';$values=$save??$values;}}
require __DIR__.'/_head.php';?>
<?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<div class="alert alert-info">এই পেজ থেকে হোমপেজের বিজ্ঞপ্তি শিরোনামের নিচে প্রদর্শিত সর্বোচ্চ তিনটি বার্তা আলাদাভাবে পরিচালনা করুন। বার্তা দীর্ঘ হলেও হোমপেজে সংক্ষিপ্ত অংশ দেখাবে; সম্পূর্ণ বার্তা পপ-আপে খুলবে। ছবি ঐচ্ছিক। JPG, PNG বা WEBP, সর্বোচ্চ ৫ MB।</div>
<form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>">
<?php for($i=1;$i<=3;$i++):$v=$values[$i];?><div class="panel mb-4"><div class="d-flex align-items-center justify-content-between gap-2 mb-3"><div><div class="section-label">বার্তা প্রোফাইল <?=$i?></div><div class="hint">নাম, পদবি, বার্তা ও প্রোফাইল ছবি</div></div><span class="badge text-bg-light">হোমপেজ কার্ড <?=$i?></span></div><div class="row g-3"><div class="col-12 col-md-4"><label class="form-label" for="message<?=$i?>_name">নাম</label><input class="form-control" id="message<?=$i?>_name" name="message<?=$i?>_name" maxlength="180" value="<?=e($v['name'])?>" placeholder="ব্যক্তির পূর্ণ নাম"></div><div class="col-12 col-md-4"><label class="form-label" for="message<?=$i?>_role">পদবি</label><input class="form-control" id="message<?=$i?>_role" name="message<?=$i?>_role" maxlength="180" value="<?=e($v['role'])?>" placeholder="যেমন: প্রতিষ্ঠাতা / অধ্যক্ষ"></div><div class="col-12 col-md-4"><label class="form-label" for="message<?=$i?>_photo_upload">প্রোফাইল ছবি</label><input class="form-control" type="file" id="message<?=$i?>_photo_upload" name="message<?=$i?>_photo_upload" accept="image/jpeg,image/png,image/webp"><?php if($v['photo']!==''):?><img src="../../<?=e($v['photo'])?>" alt="বর্তমান প্রোফাইল ছবি" style="width:74px;height:74px;object-fit:cover;border-radius:50%;margin-top:10px;border:3px solid #e7f5f5"><div class="hint">নতুন ছবি না দিলে বর্তমান ছবিই থাকবে।</div><?php endif;?></div><div class="col-12"><label class="form-label" for="message<?=$i?>_text">সম্পূর্ণ বার্তা</label><textarea class="form-control" id="message<?=$i?>_text" name="message<?=$i?>_text" rows="6" maxlength="12000" placeholder="সম্পূর্ণ বার্তাটি এখানে লিখুন..."><?=e($v['text'])?></textarea><div class="hint mt-1">সর্বোচ্চ ১২,০০০ অক্ষর। হোমপেজে সংক্ষিপ্ত অংশ ও “সম্পূর্ণ বার্তা পড়ুন” বাটন দেখা যাবে। নাম ও বার্তা পূরণ করা থাকলেই কার্ডটি প্রকাশিত হবে।</div></div></div></div><?php endfor;?>
<div class="d-flex flex-wrap gap-2 mb-4"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk me-1"></i> বার্তা ও প্রোফাইল সংরক্ষণ করুন</button><a class="btn btn-outline-secondary" href="../../#notices" target="_blank" rel="noopener">হোমপেজে দেখুন</a></div></form>
